CREATE OR REPLACE PROCEDURE t1 AS
  v_x NUMBER := 2;
  v_y NUMBER;
BEGIN
  SELECT SUM(v_x * usage_duration_hours) INTO v_y FROM usage_records;
END;

CREATE OR REPLACE PROCEDURE t2 AS
  v_x NUMBER := 2;
  v_y NUMBER;
BEGIN
  SELECT SUM(v_x * 1) INTO v_y FROM dual;
END;

CREATE OR REPLACE PROCEDURE t3 AS
  v_x NUMBER := 2;
  v_y NUMBER;
BEGIN
  SELECT NVL(SUM(CASE WHEN 1=1 THEN v_x * 1 ELSE v_x * 2 END),0) INTO v_y FROM dual;
END;

