    WHERE ac_id = r_ac.ac_id;

    SELECT AVG(indoor_temperature_celsius), AVG(outdoor_temperature_celsius)
      INTO v_avg_indoor, v_avg_outdoor
    FROM usage_records
    WHERE ac_id = r_ac.ac_id;
    v_avg_indoor := NVL(v_avg_indoor, 24.0);
    v_avg_outdoor := NVL(v_avg_outdoor, 30.0);

    SELECT NVL(SUM(CASE WHEN "mode" = 'Cooling'
                        THEN v_cooling_kw * usage_duration_hours
                        ELSE v_heating_kw * usage_duration_hours
                   END),0)
      INTO v_output
    FROM usage_records
    WHERE ac_id = r_ac.ac_id;

    IF v_pre_total > 0 THEN
      v_seasonal_eff := v_output / v_pre_total;
    ELSE
      v_seasonal_eff := r_ac.energy_efficiency_ratio;
    END IF;

    IF v_pre_total > 0 AND v_total_hours > 0 THEN
      v_avg_power_kw := v_pre_total / v_total_hours;
    ELSE
      v_avg_power_kw := r_ac.power_consumption_watts / 1000.0;
    END IF;

    IF v_avg_outdoor - v_avg_indoor > 0 THEN
      v_carnot_coef := (v_avg_indoor + 273.15) / (v_avg_outdoor - v_avg_indoor);
      IF v_seasonal_eff > v_carnot_coef THEN
        v_seasonal_eff := v_carnot_coef;
      END IF;
    END IF;

    SELECT MAX(phase_change_heat_kj_per_kg), AVG(refrigerant_flow_rate_kg_per_s)
      INTO v_phase_change, v_actual_flow
    FROM refrigerant_properties
    WHERE refrigerant_type = r_ac.refrigerant_type;

    v_phase_change := NVL(v_phase_change, 200);
    v_actual_flow := NVL(v_actual_flow, v_cooling_kw / 200);

    IF v_phase_change > 0 THEN
      v_required_flow := v_cooling_kw / v_phase_change;
      IF v_actual_flow < v_required_flow * para_flow_degradation_threshold THEN

        SELECT NVL(MAX(emission_factor),0.5)
          INTO v_emission_factor
        FROM carbon_emissions;

        v_del_ids := num_tab();
        v_del_kwh := num_tab();
        SELECT energy_id, energy_consumption_kwh
          BULK COLLECT INTO v_del_ids, v_del_kwh
        FROM energy_consumption
        WHERE ac_id = r_ac.ac_id
          AND power_consumption_watts > r_ac.power_consumption_watts * 1.15
          AND outdoor_temperature_celsius > para_outdoor_heat_threshold
        ORDER BY energy_id;

        IF v_del_ids.COUNT > 0 THEN
          FOR i IN 1..v_del_ids.COUNT LOOP
            DELETE FROM energy_consumption WHERE energy_id = v_del_ids(i);
          END LOOP;
        END IF;

        SELECT NVL(SUM(energy_consumption_kwh),0)
          INTO v_post_total
        FROM energy_consumption
        WHERE ac_id = r_ac.ac_id;

        IF v_post_total > 0 THEN
          v_post_eff := v_output / v_post_total;
        ELSE
          v_post_eff := r_ac.energy_efficiency_ratio;
        END IF;

        IF v_post_total > 0 AND v_total_hours > 0 THEN
          v_post_avg_power_kw := v_post_total / v_total_hours;
        ELSE
          v_post_avg_power_kw := r_ac.power_consumption_watts / 1000.0;
        END IF;

        IF v_avg_outdoor - v_avg_indoor > 0 THEN
          v_carnot_coef := (v_avg_indoor + 273.15) / (v_avg_outdoor - v_avg_indoor);
          IF v_post_eff > v_carnot_coef THEN
            v_post_eff := v_carnot_coef;
          END IF;
        END IF;

        IF v_post_eff < r_ac.energy_efficiency_ratio * para_eer_degradation_ratio THEN
          UPDATE air_conditioner_info
             SET energy_efficiency_ratio = v_post_eff,
                 power_consumption_watts = v_post_avg_power_kw * 1000.0
           WHERE ac_id = r_ac.ac_id;
        END IF;

        INSERT INTO carbon_emissions(id, emission_factor, annual_emissions_tonnes)
        VALUES (v_next_id, v_emission_factor, v_pre_total * v_emission_factor / 1000.0);
        v_next_id := v_next_id + 1;

        IF v_del_ids.COUNT > 0 THEN
          FOR i IN 1..v_del_ids.COUNT LOOP
            INSERT INTO carbon_emissions(id, emission_factor, annual_emissions_tonnes)
            VALUES (v_next_id, v_emission_factor, NVL(v_del_kwh(i),0) * v_emission_factor / 1000.0);
            v_next_id := v_next_id + 1;
          END LOOP;
        END IF;

      END IF;
    END IF;

  END LOOP;
  CLOSE c_ac;
END sp;
